package pzvrphysicality;
import java.io.*;import java.nio.file.*;import java.util.*;import zombie.iso.*;import zombie.iso.objects.*;import zombie.core.skinnedmodel.model.*;import zombie.core.skinnedmodel.model.jassimp.*;import zombie.core.skinnedmodel.animation.AnimationTrack;import viewpoint.core.Frame;
/** Native animated branch and same-instance source invalidation, without provider factories. */
public final class BasileNativeClockTest {
 private static int checks;private static void check(boolean v,String why){if(!v)throw new AssertionError(why);checks++;}
 private static final String KEY="carpentry_carpentry_01_48",MODEL="BasileDoors3D."+KEY,ALIAS="carpentry_01_48";
 private static ProcessedAiScene processed(Path data)throws Exception{try(var in=new DataInputStream(Files.newInputStream(data))){int v=in.readInt(),n=in.readInt();var a=new VertexBufferObject.VertexArray(v);float[] positions=new float[v*3];int[] faces=new int[n];for(int i=0;i<positions.length;i++)positions[i]=in.readFloat();for(int i=0;i<n;i++)faces[i]=in.readInt();for(int i=0;i<v;i++)for(int c=0;c<4;c++)a.data[i][1][c]=in.readFloat();for(int i=0;i<v;i++)for(int c=0;c<4;c++)a.data[i][2][c]=in.readInt();for(int i=0;i<v;i++)for(int c=0;c<3;c++)a.data[i][0][c]=positions[i*3+c];check(in.read()==-1&&v==360&&n==540,"independent original native leaf extent");return new ProcessedAiScene(new ImportedSkinnedMesh(a,faces));}}
 private static void offer(IsoDoor d,Frame f,ModelMesh mesh,SpriteModel model){f.scene.models.clear();f.scene.models.skin(DoorMeshCpuTest.identity(),1);f.drawers.clear();f.drawers.add(new IsoObjectModelDrawer(model,mesh));NativeDoorCapture.begin(f,d,0);f.scene.models.add(mesh,NativeDoorCaptureTest.matrix(),0);NativeDoorCapture.end(f,d,true);}
 public static void main(String[] args)throws Exception{
  Path media=Path.of(args[2]).resolve("native-provider/mods/BasileDoors3D/42/media");Files.createDirectories(media.resolve("java/client"));Files.createDirectories(media.resolve("models_X/BasileDoors3D"));Path jar=media.resolve("java/client/BasileDoors3D.jar");Files.copy(Path.of(args[0]),jar);Path asset=Path.of(args[0]).getParent().getParent().getParent().resolve("models_X/BasileDoors3D/"+KEY+".glb");Files.copy(asset,media.resolve("models_X/BasileDoors3D/"+KEY+".glb"));
  var source=BasileDoorAssets.verify(jar,basile.doors3d.DoorModels.class,basile.doors3d.DoorCatalog.class);var sf=BasileDoorAssets.class.getDeclaredField("selected");sf.setAccessible(true);sf.set(null,source);zombie.ZomboidFileSystem.root=source.root;var mesh=new ModelMesh("BasileDoors3D/"+KEY);mesh.skinningData=new SkinningData();DoorMeshCpu.capture(processed(Path.of(args[1])),mesh);check(DoorMeshCpu.get(mesh)!=null,"verified native animated asset captured");
  var p=NativeDoorCaptureTest.player();var d=NativeDoorCaptureTest.door(p);d.sprite.name=ALIAS;var raw=d.spriteModel;raw.name="Base.carpentry_01_48";raw.runtime=null;var effective=new SpriteModel();effective.name=MODEL;effective.texture="BasileDoors3D/special";effective.runtime="standard_door w closed";basile.doors3d.DoorModels.bind(d,effective);basile.doors3d.DoorCatalog.set(ALIAS,new basile.doors3d.DoorCatalog.Entry(MODEL,"BasileDoors3D/special",false,false,null,null,"Base.carpentry_01_48","w"));var f=new Frame();WorldContactCapture.requestItems(true);WorldContactCapture.scope(p);NativeDoorCapture.clear();offer(d,f,mesh,effective);check(NativeDoorCapture.sample(p).size()==1,"non-explicit provider preserves original native animation clock requirement");
  raw.runtime="changed-source-runtime";check(NativeDoorCapture.sample(p).isEmpty(),"same raw instance changed runtime retires cached provider collision");raw.runtime=null;offer(d,f,mesh,effective);check(NativeDoorCapture.sample(p).size()==1,"new coherent original source/drawer recovers same item without replay");
  raw.name="OtherProvider.Door";offer(d,f,mesh,effective);check(NativeDoorCapture.sample(p).isEmpty()&&NativeDoorCapture.owns(d),"changed source model fails current catalog predicate without borrowing a stale provider drawer");var nativeMesh=NativeDoorCaptureTest.mesh();f.scene.models.clear();f.scene.models.skin(DoorMeshCpuTest.identity(),1);f.drawers.clear();f.drawers.add(new IsoObjectModelDrawer(raw,nativeMesh));NativeDoorCapture.begin(f,d,0);f.scene.models.add(nativeMesh,NativeDoorCaptureTest.matrix(),0);NativeDoorCapture.end(f,d,true);check(NativeDoorCapture.sample(p).size()==1,"exact raw native fallback drawer preserves original native collision after provider mapping rejection");raw.name="Base.carpentry_01_48";check(NativeDoorCapture.sample(p).isEmpty(),"native fallback cannot survive renewed provider selection");offer(d,f,mesh,effective);
  raw.translate.x=.1f;check(NativeDoorCapture.sample(p).isEmpty(),"same raw instance changed transform retires previous contact");offer(d,f,mesh,effective);check(NativeDoorCapture.sample(p).isEmpty(),"stale effective clone cannot borrow newly changed original pose");effective.translate.set(raw.translate);offer(d,f,mesh,effective);check(NativeDoorCapture.sample(p).size()==1,"fresh copied pose reaches a new current provider contact");
  IsoObjectAnimations.reset();offer(d,f,mesh,effective);check(NativeDoorCapture.sample(p).isEmpty(),"ordinary weighted native leaf does not gain explicit-pose clock exemption");IsoObjectAnimations.set(d,new AnimationTrack());offer(d,f,mesh,effective);check(NativeDoorCapture.sample(p).size()==1,"native clock recovery admits only new final capture");
  d.spriteModel=null;offer(d,f,mesh,effective);check(NativeDoorCapture.sample(p).isEmpty(),"non-allowMissing profile cannot bypass missing native cache");
  check(IsoObject.lazyCalls==0&&IsoObjectAnimations.builds==0,"no original native factories executed");System.out.println("Basile native clock: "+checks+" checks passed");
 }
}
